#include "apps.h"
#include "app_stage_e.h"
#include "heap.h"
#include "fat32.h"
#include "keyboard.h"
#define SIG_MAX 8
#define SIG_PATH "/disk/Sanctum/system/notifications.log"
typedef struct{char from[24],title[48],body[72];uint8_t lane;bool read;}sig_item_t;
typedef struct{sig_item_t item[SIG_MAX];int selected,tab,count;char status[48];}signal_t;
static void sig_save(signal_t*s){if(!fat32_is_mounted()){se_copy(s->status,"Not saved - RAM only",48);return;}fat32_mkdir_p("/disk/Sanctum/system");char b[64];int n=0;for(int i=0;i<s->count;i++){b[n++]=(char)('0'+s->item[i].lane);b[n++]=s->item[i].read?'1':'0';b[n++]='\n';}if(fat32_save_file(SIG_PATH,b,n)<0)se_copy(s->status,"save failed",48);else se_copy(s->status,"signal state saved",48);}
static void sig_draw(window_t*w,const gfx_target_t*t){signal_t*s=w->user_data;const ui_runtime_theme_t*h=ui_theme_current();gfx_clear(t,h->canvas);se_header(t,"SIGNAL - MAIL BY PRESSURE","Signal",false);const char*lanes[3]={"Needs you","Later today","Settled"};int colw=(w->width-196)/3;for(int g=0;g<3;g++){int x=78+g*(colw+20);se_bold(t,x,110,lanes[g],h->ink);int y=146;for(int i=0;i<s->count;i++)if(s->item[i].lane==g){se_card(t,x,y,colw,112,h->surface,i==s->selected?h->accent_coral:h->border);gfx_fill_rect_gradient(t,x+18,y+20,22,22,h->accent_orange,h->accent_berry);se_bold(t,x+52,y+19,s->item[i].from,h->ink);se_bold(t,x+20,y+52,s->item[i].title,h->ink);se_text(t,x+20,y+77,s->item[i].body,h->muted);y+=134;}}
se_card(t,78,574,w->width-118,92,h->surface,h->border);se_bold(t,142,602,"Signal sorts by pressure, not by folder.",h->ink);se_text(t,142,628,"Move a card right with Enter; D dismisses; S snoozes.",h->muted);se_card(t,78,690,410,188,h->surface,h->border);se_text(t,104,716,"PRESSURE RULES",h->muted);se_text(t,104,758,"mentions me by name     needs you",h->ink);se_text(t,104,800,"asks for a decision     needs you",h->ink);se_text(t,104,842,"machine reports          settled",h->ink);se_card(t,510,690,410,188,h->surface,h->border);se_text(t,536,716,"DRAFTS HELD",h->muted);se_bold(t,536,758,"3 waiting on you",h->ink);se_text(t,536,800,"Nothing sends itself.",h->muted);se_card(t,942,690,w->width-982,188,h->surface,h->border);se_text(t,968,716,"QUIET BAND",h->muted);se_bold(t,968,758,"until 17:00",h->ink);se_progress(t,968,804,w->width-1030,180,h->border,h->accent_berry);se_text(t,78,w->height-34,s->status,h->accent_berry);}
static void sig_key(window_t*w,char c){signal_t*s=w->user_data;if(c==27){sig_save(s);se_close(w);return;}if(c==KBD_KEY_LEFT||c==KBD_KEY_UP)s->selected=(s->selected+s->count-1)%s->count;else if(c==KBD_KEY_RIGHT||c==KBD_KEY_DOWN||c=='\t')s->selected=(s->selected+1)%s->count;else if(c=='\n'||c==' '){s->item[s->selected].read=true;if(s->item[s->selected].lane<2)s->item[s->selected].lane++;sig_save(s);}else if(c=='s'||c=='S'){s->item[s->selected].lane=1;sig_save(s);}else if(c=='d'||c=='D'){s->item[s->selected].lane=2;s->item[s->selected].read=true;sig_save(s);}}
static void sig_click(window_t*w,int x,int y){signal_t*s=w->user_data;int cw=(w->width-196)/3;for(int g=0;g<3;g++){int xx=78+g*(cw+20),yy=146;for(int i=0;i<s->count;i++)if(s->item[i].lane==g){if(x>=xx&&x<xx+cw&&y>=yy&&y<yy+112){s->selected=i;return;}yy+=134;}}}
window_t* app_signal_open(void){signal_t*s=kmalloc(sizeof(*s));if(!s)return 0;s->count=8;s->selected=0;s->tab=0;const char*f[SIG_MAX]={"Prism team","Mesh watch","Ilse Marek","CHRT store","Alyu","Strata","Ignite","Core"};const char*ti[SIG_MAX]={"Ring rotation decision","Key rotation in 3 hours","Sign off the icon grammar","Two prisms updated","Note to self","Cold layer offloaded","Boot report","Guardrail report"};const char*bo[SIG_MAX]={"Two prototypes attached - we need a call today.","Nothing to do unless you want to defer.","One page, four rules. I only need a yes.","Sound and Beacon moved to 1.0.3.","Write the grammar page before review.","18 GB reclaimed overnight.","Cold start 1.9s across 3 devices.","7 armed - nothing tripped this week."};for(int i=0;i<SIG_MAX;i++){se_copy(s->item[i].from,f[i],24);se_copy(s->item[i].title,ti[i],48);se_copy(s->item[i].body,bo[i],72);s->item[i].lane=i<3?0:i<5?1:2;s->item[i].read=i>=5;}char b[64];int64_t n=fat32_read_file(SIG_PATH,b,sizeof(b));if(n>0)for(int i=0;i<s->count&&i*3+1<n;i++){s->item[i].lane=(uint8_t)(b[i*3]-'0');s->item[i].read=b[i*3+1]=='1';}se_copy(s->status,fat32_is_mounted()?"Enter settle  S snooze  D dismiss":"Not saved - RAM only",48);window_t*w=se_workspace("Signal",sig_draw,sig_click,sig_key,s,false);if(!w)kfree(s);return w;}
